//! Independent oracle: [AMD PAL addrlib](https://github.com/GPUOpen-Drivers/pal/tree/c5e800072a32f68b6ccc4422936d96167c6e0728/src/core/imported/addrlib).
//! The constants below were generated by calling its public C API, not by porting the
//! swizzle table or using `Layout` to generate input. No GPU or game data is involved.
//!
//! To regenerate, build addrlib with `ADDR_GFX10_BUILD`; zero-init the public API
//! structs, set their `size` fields, and supply malloc/free callbacks to `AddrCreate`.
//! Set `chipEngine=0x0d`, `chipFamily=0x8f`, `chipRevision=1`, `regValue.gbAddrConfig=0`,
//! `createFlags.fillSizeFields=1`. This picks the Navi10 (non-RB+) branch; GFX10's
//! `HwlInitGlobalParams` decodes this synthetic register as one pipe, 256-byte interleave.
//! It is not a claim about any physical device's configuration.
//!
//! For each (width,height) below, call `Addr2ComputeSurfaceAddrFromCoord` in dense row
//! order with `unalignedWidth=width`, `unalignedHeight=height`, `resourceType=ADDR_RSRC_TEX_2D`,
//! `swizzleMode=ADDR_SW_64KB_R_X`, `flags.color=1`, `bpp=32`, and `numSlices`,
//! `numMipLevels`, `numSamples`, `numFrags` all 1. Only x and y vary; `pipeBankXor`,
//! `slice`, `sample`, `mipId` and `pitchInElement` remain zero. For every `ADDR_OK`
//! result, append LE32(`out.addr ^ 0x76543210`); FNV-1a-64 of those bytes is the digest.
//! Negative control: change *only* `gbAddrConfig` to 1 (two pipes). On the same
//! 259×131 surface, (63,64) moves from byte offset `0x6a8c` to `0x6b8c` and
//! the digest becomes `328f2914f21585d8`. Geometry cannot select this profile.

use victory_formats::texture::{Desc, Dimension, Layout, Swizzle, copy_gfx10_1pipe_rx_rgba8};

const BLOCK_BYTES: usize = 65536;
const TAG: u32 = 0x7654_3210;
const SENTINEL: u8 = 0xcd;

fn desc(width: u32, height: u32) -> Desc {
    Desc {
        dimension: Dimension::Tex2d,
        width,
        height,
        depth: 1,
        mips: 1,
        element_bytes: 4,
        block: 1,
        samples: 1,
        swizzle: Swizzle::SW_64KB_R_X,
    }
}

#[test]
fn visible_address_tags_match_addrlib_for_every_texel() {
    for (width, height, blocks, digest) in [
        (11, 7, 1, 0x202f_d552_f0dc_9e9b_u64),
        (128, 128, 1, 0xb5b7_58f2_0f4d_4325),
        (259, 131, 6, 0xeaa4_c426_83a8_7bd8),
    ] {
        let layout = Layout::new(&desc(width, height)).unwrap();
        // An exact profile must be supplied out-of-band; a generic Layout alone
        // must still not advertise an address equation for this swizzle.
        assert!(!layout.addressable());
        // Every physical word, including those in padding, has a unique tag.
        let mut tiled = Vec::with_capacity(blocks * BLOCK_BYTES);
        for addr in (0..(blocks * BLOCK_BYTES) as u32).step_by(4) {
            tiled.extend_from_slice(&(addr ^ TAG).to_le_bytes());
        }
        let n = (width * height * 4) as usize;
        let mut rows = vec![SENTINEL; n + 9];
        copy_gfx10_1pipe_rx_rgba8(&layout, &tiled, &mut rows).unwrap();
        if blocks == 6 {
            // Raw Addr2 byte offsets, for diagnostics on micro-/macro-block boundaries.
            for (x, y, addr) in [
                (5, 3, 0xb4),
                (63, 64, 0x6a8c),
                (127, 127, 0xfffc),
                (128, 127, 0x15570),
                (127, 128, 0x3aa8c),
                (129, 129, 0x40014),
                (258, 130, 0x50028),
            ] {
                let i = (4 * (y * width + x)) as usize;
                assert_eq!(rows[i..i + 4], (addr ^ TAG).to_le_bytes(), "({x},{y})");
            }
        }
        let hash = rows[..n].iter().fold(0xcbf2_9ce4_8422_2325_u64, |h, &b| {
            (h ^ u64::from(b)).wrapping_mul(0x100_0000_01b3)
        });
        assert_eq!(hash, digest, "visible {width}x{height} texels");
        assert_eq!(rows[n..], [SENTINEL; 9], "wrote beyond dense rows");
    }
}

fn assert_rejected(layout: &Layout, source_len: usize, dest_len: usize) {
    let source = vec![0x17; source_len];
    let mut dest = vec![SENTINEL; dest_len];
    assert!(copy_gfx10_1pipe_rx_rgba8(layout, &source, &mut dest).is_err());
    assert!(
        dest.iter().all(|&b| b == SENTINEL),
        "partial write on error"
    );
}

#[test]
fn truncated_padding_short_rows_and_inconsistent_geometry_do_not_write() {
    let layout = Layout::new(&desc(259, 131)).unwrap();
    let plane = 6 * BLOCK_BYTES;
    let n = 259 * 131 * 4;
    assert_rejected(&layout, plane - 1, n);
    assert_rejected(&layout, plane, n - 1);
    let mut bad_pitch = layout.clone();
    bad_pitch.mips[0].pitch -= 128;
    assert_rejected(&bad_pitch, plane, n);
    let mut no_mip = layout;
    no_mip.mips.clear();
    assert_rejected(&no_mip, plane, n);
}

#[test]
fn other_descriptions_do_not_select_this_equation() {
    let d = desc(11, 7);
    for other in [
        Desc {
            swizzle: Swizzle::SW_64KB_D_X,
            ..d
        },
        Desc {
            dimension: Dimension::Tex3d,
            ..d
        },
        Desc { depth: 2, ..d },
        Desc { samples: 2, ..d },
        Desc { mips: 2, ..d },
        Desc { block: 4, ..d },
        Desc {
            element_bytes: 8,
            ..d
        },
    ] {
        let layout = Layout::new(&other).unwrap();
        let n = layout.size as usize;
        assert_rejected(&layout, n, n);
    }
}
